content.solution_code:
class MusicalInstrument {
    constructor(brand) {
        this.brand = brand;
    }

    play() {
        return this.brand + ' is producing a generic sound.';
    }
}

class ElectricGuitar extends MusicalInstrument {
    constructor(brand, numberOfStrings) {
        super(brand);
        this.numberOfStrings = numberOfStrings;
    }

    play() {
        return this.brand + ' is shredding a riff!';
    }
}

class SnareDrum extends MusicalInstrument {
    constructor(brand, diameterInches) {
        super(brand);
        this.diameterInches = diameterInches;
    }

    play() {
        return this.brand + ' is hitting a rhythmic beat!';
    }
}

// Test cases
const genericInstrument = new MusicalInstrument('GenericBrand');
console.log(genericInstrument.play());

const guitar = new ElectricGuitar('Fender', 6);
console.log(guitar.play());

const drum = new SnareDrum('Pearl', 14);
console.log(drum.play());

